class Color {
  private static readonly TRANSPARENT = new Color(0, 0, 0, 0);

  private constructor(public r: number, public g: number, public b: number, public a: number) {}

  static fromRgb(r: number, g: number, b: number): Color {
    return new Color(r, g, b, 255);
  }

  static fromHex(hex: string): Color {
    const [r, g, b] = parseHex(hex);
    return new Color(r, g, b, 255);
  }

  // Reuses one cached instance instead of allocating every time
  static transparent(): Color {
    return Color.TRANSPARENT;
  }
}

const red = Color.fromHex("#FF0000"); // self-documenting
const clear = Color.transparent(); // no new allocation
